-- Migration 077: one categorisation vocabulary, and no more fallback garbage
-- in the token metadata columns.
--
-- Two problems, both from values that were never validated on the way in.
--
-- 1. Token metadata on contracts that are not tokens.
--    A contract with no `name()` still answers the call: execution falls into
--    its fallback function, which typically returns the calldata it was
--    handed. Probing a wallet proxy for `name()` therefore returns the
--    selector 0x06fdde03 right-padded to a word, and the old latin-1 decoder
--    turned those bytes into a printable-but-meaningless Latin-1 string
--    (U+0006 U+00FD U+00DE U+0003). Same for `symbol()`: 0x95d89b41.
--    Confirmed live against 0x433b891eee2794693051940aed9cf6307f4ea9b7, which
--    returns exactly its own selector for all three probes.
--
--    src/lib/token-metadata.ts now rejects selector echoes, gates on ERC-20
--    bytecode surface, and decodes strictly as UTF-8 (which alone rejects the
--    0xFD 0xDE byte pair). This migration clears what the old code wrote.
--
--    Only provably-noise values are cleared: control characters, U+FFFD, or
--    empty strings -- 541 rows. Genuine oddities are deliberately preserved:
--    early tokens really do use '%', '^', a heart, 'Ͼ' and a unicorn emoji as
--    their symbol, and 0x553f5083 really does have a 298-character symbol.
--
-- 2. Five hand-maintained taxonomies that disagreed with each other.
--    `HeuristicContractType`, `getContractTypeLabel`, the /types landing page,
--    the sitemap and the category multi-select each carried their own list,
--    and `contract_type` accepted arbitrary free text on top. The documented
--    set held 30 distinct spellings, including 'Token' vs 'token', 'NFT' vs
--    'nft', 'registrar' vs 'registry', and 'governance' vs 'dao' -- so there
--    was no single way to find, say, every multisig. All five now derive from
--    CONTRACT_CATEGORY_OPTIONS in src/lib/contract-categories.ts. This
--    migration folds the stored values onto the same 20 canonical keys and
--    mirrors each contract's type into `manual_categories`.
--
-- Scope: part 1 covers every row carrying token metadata. Parts 2-4 cover the
-- 2,321 editorially documented contracts (short_description IS NOT NULL). The
-- heuristic `contract_type` on the ~1.36M undocumented rows is left alone --
-- 1.18M of those are 'other', which is a separate backfill decision.
--
-- Reversible: pre-change values for every touched row are copied into
-- `_backup_077_contract_categories` first. Rollback statement at the bottom.
--
-- Idempotent: re-running is a no-op (the backup INSERT is ON CONFLICT DO
-- NOTHING, and every UPDATE is already-normalised-safe).
--
-- None of the columns written here are in the watch list of
-- `trg_refresh_is_documented`, so no cluster recomputation is triggered.

BEGIN;

-- ============================================================================
-- 0. Backup
-- ============================================================================

CREATE TABLE IF NOT EXISTS _backup_077_contract_categories (
  address TEXT PRIMARY KEY,
  contract_type TEXT,
  manual_categories JSONB,
  token_name TEXT,
  token_symbol TEXT,
  token_decimals INTEGER,
  is_erc20_like BOOLEAN,
  backed_up_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

INSERT INTO _backup_077_contract_categories
  (address, contract_type, manual_categories, token_name, token_symbol, token_decimals, is_erc20_like)
SELECT address, contract_type, manual_categories, token_name, token_symbol, token_decimals, is_erc20_like
FROM contracts
WHERE (short_description IS NOT NULL AND short_description <> '')
   OR token_name IS NOT NULL
   OR token_symbol IS NOT NULL
ON CONFLICT (address) DO NOTHING;

-- ============================================================================
-- 1. Clear fallback garbage from the token metadata columns
-- ============================================================================

-- 1a. Names that are control characters, replacement characters, or blank.
--     Expected: 547 rows.
UPDATE contracts
SET token_name = NULL
WHERE token_name IS NOT NULL
  AND (
    token_name ~ '[\x01-\x1F\x7F-\x9F]'
    OR position(U&'\FFFD' IN token_name) > 0
    OR btrim(token_name) = ''
  );

-- 1b. Same for symbols. Expected: 545 rows.
UPDATE contracts
SET token_symbol = NULL
WHERE token_symbol IS NOT NULL
  AND (
    token_symbol ~ '[\x01-\x1F\x7F-\x9F]'
    OR position(U&'\FFFD' IN token_symbol) > 0
    OR btrim(token_symbol) = ''
  );

-- 1c. `decimals` came from the same fallback probe, so it only means anything
--     if a name or symbol survived. Explicit address list (135 rows) rather
--     than a predicate, so this cannot touch a contract whose decimals were
--     read from a real ERC-20.
UPDATE contracts
SET token_decimals = NULL
WHERE address IN
(
  '0x90077edfd1ecca420b5023bdfd42e97114ecf1db', '0xa5f88dcb14b3e66b3a74deb4b7a20cf3f46e7a5c', '0xd1dd82d14eeca38e56b8080c9eed9e0efe221e27', '0x5f11a48230f7cdab91a2361576239091e4b1165b',
