-- 1d. Demote `is_erc20_like` only where the bytecode confirms there is no
--     ERC-20 surface: no balanceOf/transfer/totalSupply selectors in the
--     dispatcher, no Transfer event topic, and not a delegating proxy. These
--     12 addresses were checked individually with looksLikeTokenContract()
--     against their stored runtime bytecode. Contracts whose metadata probe
--     merely failed keep the flag.
UPDATE contracts
SET is_erc20_like = FALSE
WHERE address IN
(
  '0x6e715ab4f598eacf0016b9b35ef33e4141844ccc', '0x630a0cd35d5bd57e61410fda76fea850225cda18', '0xc7aa8ebbb172de6cbfb82bb213b14896248a4824', '0x038ddc33db89d12c4b92607f9ed4a5d6d0d84c2e',
