  '0x09c17eb7019bca47de666ea1ede6a2613cdf56d3', '0x5457f683d0a417fb3b228e8728431a235471f734', '0xe3a7bdea3a61ae3d797110167da92d14120fdd7a', '0x012cfe5cc20b510f74453020f302d59ab62739cf'
);

-- ============================================================================
-- 2-4. Fold `contract_type` onto the canonical vocabulary and mirror it into
--      `manual_categories`.
--
-- Each statement below is one (type, categories) target. Two mechanisms
-- produced these lists:
--
--   * synonym folds of existing values -- registrar -> registry,
--     governance -> dao, vending-machine -> exchange, Token -> token,
--     NFT -> nft, gambling -> lottery, program/initializer ->
--     experimental, other -> unknown. (116 rows)
--
--   * reclassification of rows that were untyped or 'unknown' but whose own
--     description opens by naming what they are -- "Owner-controlled deposit
--     wallet (Homestead, Jul 2016): ...", "Minimal two-party escrow with an
--     arbitrator", "The classic Frontier 'greeter'". Only the opening clause
--     is matched, because later sentences reference *other* contracts
--     ("Sibling of the verified MessagingContract / Ponzi / ...") and matching
--     those labelled an oracle as a lottery. (1,569 rows)
--
--   * 7 rows a historian had explicitly categorised while the heuristic still
--     said 'unknown' -- the type is taken from the historian's category
--     rather than left contradicting it.
--
-- Net effect on the documented set: 30 free-text spellings -> 20 canonical
-- keys in use (of 21 available), and 1,353 wallet contracts that were
-- previously untyped become findable at /types/wallet.
-- ============================================================================

-- 1353 contract(s) -> type wallet, categories ["wallet"]
UPDATE contracts SET contract_type = 'wallet', manual_categories = '["wallet"]'::jsonb
WHERE address IN (
  '0x0011d2d4f8d91d955b7fedbe04d8a0600ea657f2', '0x0062bc7b101656e9590753b260abbf0747c7e57a', '0x0065d01fd56b5c8c01683cdbc8c2b69656f05008', '0x00c68c52a753bbe81f28e2f9c48bb73f0183fcef',
